#![allow(clippy::excessive_precision)]

use thermopack_rs::SolidCo2;

const QUANTITIES: [&str; 13] = [
    "gibbs",
    "dg_dp",
    "d2g_dp2",
    "dg_dt",
    "d2g_dt2",
    "d2g_dtdp",
    "specific_volume",
    "entropy",
    "enthalpy",
    "internal_energy",
    "helmholtz",
    "heat_capacity",
    "speed_of_sound",
];
const ATOL: [f64; 13] = [
    1e-6, 1e-16, 1e-26, 1e-9, 1e-14, 1e-17, 1e-16, 1e-9, 1e-6, 1e-6, 1e-6, 1e-9, 1e-6,
];
const RTOL: f64 = 1e-11;

#[test]
fn solid_co2_matches_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/solid_co2.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<f64> = case
            .split('|')
            .skip(1)
            .map(|value| value.parse().unwrap())
            .collect();
        let mut model = SolidCo2::new();
        model.initialize(parts[0], parts[1], parts[2], parts[3]);
        let temperature = parts[4];
        let pressure = parts[5];
        let actual = [
            model.gibbs(temperature, pressure),
            model.dg_dp(temperature, pressure),
            model.d2g_dp2(temperature, pressure),
            model.dg_dt(temperature, pressure),
            model.d2g_dt2(temperature, pressure),
            model.d2g_dtdp(temperature, pressure),
            model.specific_volume(temperature, pressure),
            model.entropy(temperature, pressure),
            model.enthalpy(temperature, pressure),
            model.internal_energy(temperature, pressure),
            model.helmholtz(temperature, pressure),
            model.heat_capacity(temperature, pressure),
            model.speed_of_sound(temperature, pressure),
        ];
        let expected: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        assert_eq!(expected.len(), actual.len(), "{case}");
        for (position, (source, native)) in expected.iter().zip(actual.iter()).enumerate() {
            let tolerance = ATOL[position] + RTOL * source.abs().max(native.abs());
            assert!(
                (source - native).abs() <= tolerance,
                "{case} {}: source {source} native {native}",
                QUANTITIES[position]
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 7);
}

#[test]
fn solid_co2_reference_shift_is_reproducible() {
    // The shift must move the model onto the requested reference state: the
    // Gibbs energy of the solid at the triple point is the liquid Gibbs energy
    // reduced by the melting enthalpy.
    let mut model = SolidCo2::new();
    model.initialize(205.147591034776, -18000.0, 216.592, 517950.0);
    let gibbs = model.gibbs(216.592, 517950.0);
    let entropy = model.entropy(216.592, 517950.0);
    let enthalpy = model.enthalpy(216.592, 517950.0);
    assert!(gibbs < -18000.0);
    assert!(entropy > 0.0);
    assert!((enthalpy - gibbs - 216.592 * entropy).abs() < 1e-9);
    // The volume follows the pressure derivative of the Gibbs energy.
    let volume = model.specific_volume(216.592, 517950.0);
    assert!(volume > 0.0);
    assert!((model.dg_dp(216.592, 517950.0) - volume).abs() < 1e-18);
}
